class Solution {public boolean solve(int n,int[][] edges){ArrayList<ArrayList<Integer>>a=new ArrayList<>();for(int i=0;i<n;i++)a.add(new ArrayList<>());for(int[]e:edges){a.get(e[0]).add(e[1]);a.get(e[1]).add(e[0]);}int[] color=new int[n];Arrays.fill(color,-1);for(int s=0;s<n;s++)if(color[s]<0){ArrayDeque<Integer>q=new ArrayDeque<>();q.add(s);color[s]=0;while(!q.isEmpty()){int u=q.remove();for(int v:a.get(u))if(color[v]<0){color[v]=color[u]^1;q.add(v);}else if(color[v]==color[u])return false;}}return true;}}